CREATE TABLE price_log (product_id INTEGER, old_price REAL, new_price REAL);

CREATE TRIGGER log_price AFTER UPDATE OF price ON products
BEGIN
  INSERT INTO price_log VALUES (OLD.id, OLD.price, NEW.price);
END;

UPDATE products SET price = 12 WHERE id = 2;
SELECT * FROM price_log;

